def group_words_by_first_letter(words):
    grouped = {}
    for word in words:
        first_letter = word[0].lower()
        if first_letter not in grouped:
            grouped[first_letter] = []
        grouped[first_letter].append(word)
    return grouped

# Example usage:
# group_words_by_first_letter(['apple', 'banana', 'cherry', 'date', 'elderberry'])
# Expected output: {'a': ['apple', 'date'], 'b': ['banana'], 'c': ['cherry'], 'e': ['elderberry']}

